    io("file paths", () -> { File f = new File("/a/b/../c/./d.txt"); return f.getName() + " " + f.getParent() + " " + f.getPath() + " " + f.isAbsolute() + " " + f.getAbsolutePath() + " " + f.getCanonicalPath() + " " + new File("rel/x").isAbsolute() + " " + new File("").getPath().isEmpty() + " " + new File("/").getName().isEmpty() + " " + new File("a//b///c/").getPath() + " " + new File("/a", "b").getPath() + " " + new File((String) null, "b").getPath() + " " + new File(new File("/x"), "y/z").getPath() + " " + f.toURI() + " " + f.toPath() + " " + f.compareTo(new File("/a/b/../c/./e.txt")) + " " + f.equals(new File("/a/b/../c/./d.txt")) + " " + f.hashCode() + " " + f.toString(); });
    io("file listing", () -> { File d = java.nio.file.Files.createTempDirectory("fl").toFile(); try { new File(d, "b").mkdir(); new File(d, "a.txt").createNewFile(); new File(d, "c.java").createNewFile(); String[] names = d.list(); Arrays.sort(names); File[] fs = d.listFiles((dir, n) -> n.endsWith(".txt")); File[] fs2 = d.listFiles(File::isDirectory); StringBuilder sb = new StringBuilder(Arrays.toString(names)); sb.append(fs.length).append(fs2.length).append(new File(d, "none").list() == null).append(new File(d, "a.txt").list() == null).append(d.mkdir()).append(new File(d, "x/y/z").mkdirs()).append(new File(d, "x/y/z").isDirectory()).append(new File(d, "x").delete()); return sb; } finally { deleteTree(d); } });
